005 const TIKTOK_DIR = "C:\\Users\\sinek\\Desktop\\TIKTOK";
006 const MANIFEST_PATH = path.join(TIKTOK_DIR, "latest_maxi_tiktok_manifest.json");
007 const SCREENSHOT_PATH = path.join(TIKTOK_DIR, "latest_tiktok_publish_state.png");
008 
009 function saveManifest(manifest) {
010   fs.writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2), "utf8");
011 }
012 
013 async function bodyText(page) {
014   return await page.locator("body").innerText({ timeout: 10000 }).catch(() => "");
015 }
016 
017 async function main() {
018   if (!fs.existsSync(MANIFEST_PATH)) {
019     throw new Error(`Manifest introuvable: ${MANIFEST_PATH}`);
020   }
021 
022   const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf8"));
023   if (!manifest.video || !fs.existsSync(manifest.video)) {
024     throw new Error(`Video introuvable: ${manifest.video}`);
025   }
026 
027   const browser = await chromium.connectOverCDP("http://127.0.0.1:9222");
028   const context = browser.contexts()[0] || (await browser.newContext());
029   let page =
030     context.pages().find((p) => p.url().includes("tiktokstudio/upload")) ||
031     context.pages().find((p) => p.url().includes("tiktok.com")) ||
032     (await context.newPage());
033 
034   await page.bringToFront();
035   await page.goto("https://www.tiktok.com/tiktokstudio/upload?lang=fr", {
036     waitUntil: "domcontentloaded",
037     timeout: 60000,
038   }).catch((error) => {
039     manifest.publishStatus = "blocked";
040     manifest.publishError = `Impossible d'ouvrir TikTok Studio: ${error.message}`;
041   });
042 
043   await page.waitForTimeout(5000);
044   const initialText = await bodyText(page);
045   if (/se connecter|connexion|inscription|mot de passe|code de vérification|captcha/i.test(initialText)) {
046     manifest.publishStatus = "manual_needed";
047     manifest.publishError = "TikTok demande une connexion, un code ou une validation sensible.";
048     saveManifest(manifest);
049     await page.screenshot({ path: SCREENSHOT_PATH, fullPage: true }).catch(() => {});
050     await browser.close();
051     console.log(JSON.stringify({ status: manifest.publishStatus, reason: manifest.publishError }));
052     return;
053   }
054 
055   const fileInputs = await page.locator('input[type="file"]').count();
056   if (!fileInputs) {
057     manifest.publishStatus = "blocked";
058     manifest.publishError = "Aucun champ d'upload video trouvé sur TikTok Studio.";
059     saveManifest(manifest);
060     await page.screenshot({ path: SCREENSHOT_PATH, fullPage: true }).catch(() => {});
061     await browser.close();
062     console.log(JSON.stringify({ status: manifest.publishStatus, reason: manifest.publishError }));
063     return;
064   }
065 
066   await page.locator('input[type="file"]').first().setInputFiles(manifest.video);
067 
068   let ready = false;
069   for (let i = 0; i < 40; i++) {
070     await page.waitForTimeout(5000);
071     const text = await bodyText(page);
072     if (/Importé|Description|Publier|Vérifications|Couverture/i.test(text) && /Publier/i.test(text)) {
073       ready = true;
074       break;
075     }
076   }
077 
078   if (!ready) {
079     manifest.publishStatus = "blocked";
080     manifest.publishError = "Upload TikTok non prêt après attente.";
081     saveManifest(manifest);
082     await page.screenshot({ path: SCREENSHOT_PATH, fullPage: true }).catch(() => {});
083     await browser.close();
084     console.log(JSON.stringify({ status: manifest.publishStatus, reason: manifest.publishError }));
085     return;
086   }
087 
088   const afterUploadText = await bodyText(page);
089   if (afterUploadText.includes("Activer les vérifications automatiques")) {
090     await page.getByText("Activer", { exact: true }).click({ timeout: 10000 }).catch(() => {});
091     await page.waitForTimeout(2500);
092   }
093 
094   const caption = manifest.caption || "Maxi Trouvailles - bonnes affaires et déstockage sur https://maxitrouvaille.fr #maxitrouvailles #destockage";
095   const editor = page.locator('[contenteditable="true"]').first();
096   await editor.click({ timeout: 10000 });
097   await page.keyboard.press("Control+A");
098   await page.keyboard.press("Backspace");
099   await page.keyboard.type(caption, { delay: 4 });
100 
101   for (let i = 0; i < 30; i++) {
102     await page.waitForTimeout(5000);
103     const text = await bodyText(page);
104     if (/Aucun problème constaté/i.test(text) || (!/Vérification en cours/i.test(text) && /Publier/i.test(text))) {
105       break;
106     }
107   }
108 
109   await page.getByText("Publier", { exact: true }).click({ timeout: 15000 }).catch(async () => {
110     await page.locator("button").filter({ hasText: "Publier" }).first().click({ timeout: 15000 });
111   });
112 
113   let published = false;
114   for (let i = 0; i < 36; i++) {
115     await page.waitForTimeout(5000);
116     const text = await bodyText(page);
117     if (page.url().includes("tiktokstudio/content") && /Vidéo publiée|Contenu \(Créé le\)|Publications/i.test(text)) {
118       published = true;
119       break;
120     }

